//! Native HTMLLabelElement.form reads the associated control owner.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=seed>Choice</label><input id=field type=checkbox><div id=mount></div></form><form id=other></form><input id=external form=other></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_label_form_canonical_readonly_and_actual_native_form_owners(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),field=document.getElementById('field'),owner=document.getElementById('owner'),other=document.getElementById('other'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'form');if(!descriptor||typeof descriptor.get!=='function'||descriptor.set!==undefined||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get form'||descriptor.get.length!==0||Object.hasOwn(label,'form'))throw 'canonical label form descriptor';label.htmlFor='field';if(label.form!==owner||label.form!==field.form||descriptor.get.call(label)!==owner)throw 'actual native ancestor owner';label.htmlFor='external';if(label.form!==other||label.control!==document.getElementById('external'))throw 'control explicit form overrides label ancestry';label.htmlFor='absent';if(label.form!==null)throw 'missing labeled control';"#);}
#[test]
fn html_label_form_inert_connected_exact_form_id_and_detached_ancestor_rules(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),outer=owner.createElement('form'),other=owner.createElement('form'),label=owner.createElement('label'),field=owner.createElement('input');outer.id='outer';other.id='A\ud800z';outer.appendChild(label);label.appendChild(field);owner.body.appendChild(outer);owner.body.appendChild(other);if(label.form!==outer)throw 'actual inert ancestor owner';field.setAttribute('form','A\ud800z');if(label.form!==other)throw 'exact inert explicit form owner';var literal=owner.createElement('form');literal.id='A�z';owner.body.insertBefore(literal,other);if(label.form!==other)throw 'replacement alias is not owner';var blocker=owner.createElement('div');blocker.id='A\ud800z';owner.body.insertBefore(blocker,other);if(label.form!==null)throw 'first id match must be HTML form';owner.body.removeChild(blocker);owner.body.removeChild(outer);if(label.form!==outer)throw 'detached explicit form falls back to nearest ancestor';outer.removeChild(label);if(label.form!==null)throw 'detached no ancestor owner';"#);}
#[test]
fn html_label_form_builtin_association_namespace_brands_and_label_attribute_separation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),form=owner.createElement('form'),label=owner.createElement('label'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'form');owner.body.appendChild(form);form.appendChild(label);for(var name of ['button','input','output','select','textarea','meter','progress']){var field=owner.createElement(name);label.appendChild(field);if(label.control!==field||label.form!==((name==='meter'||name==='progress')?null:form))throw 'builtin actual form association '+name;label.removeChild(field);}var input=owner.createElement('input');label.appendChild(input);label.setAttribute('form','missing');if(label.form!==form)throw 'label has no form content authority';for(var bad of [{},Object.create(HTMLLabelElement.prototype),document,owner.createElement('div'),owner.createElementNS('urn:element','label')]){var caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine native label form brand';}label.form='ignored';if(label.form!==form)throw 'sloppy readonly';var caught=false;try{(function(){'use strict';label.form=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly';"#);}

#[test]
fn html_label_form_ignores_author_association_and_preserves_descriptor_overrides(){let(mut d,mut f,mut p)=fixture();let before=format!("{:?}",d.nodes);let error=p.runtime.execute("Object.defineProperty(document.getElementById('field'),'form',{get:function(){return null;},configurable:true});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("descriptor")||error.contains("Native"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.begin_job();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),field=document.getElementById('field'),owner=document.getElementById('owner'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'form'),calls=0;label.htmlFor='field';Object.defineProperty(label,'control',{get:function(){calls++;return null;},configurable:true});var inertOwner=document.implementation.createHTMLDocument('author'),inertForm=inertOwner.createElement('form'),inertLabel=inertOwner.createElement('label'),inertField=inertOwner.createElement('input');inertLabel.appendChild(inertField);inertForm.appendChild(inertLabel);Object.defineProperty(inertField,'form',{get:function(){calls++;return null;},configurable:true});if(inertLabel.form!==inertForm||calls)throw 'inert form owner ignores author getter';if(label.form!==owner||calls)throw 'actual associated owner ignores author getters';Object.defineProperty(label,'form',{value:'own',writable:true,configurable:true});label.form='updated';if(label.form!=='updated'||descriptor.get.call(label)!==owner)throw 'writable ordinary own shadow';delete label.form;Object.defineProperty(HTMLLabelElement.prototype,'form',{get:function(){return 'prototype';},configurable:true});if(label.form!=='prototype'||descriptor.get.call(label)!==owner)throw 'prototype override';delete HTMLLabelElement.prototype.form;if(label.form!==undefined||descriptor.get.call(label)!==owner)throw 'deleted canonical descriptor';Object.defineProperty(HTMLLabelElement.prototype,'form',descriptor);var count=0;for(var key in label)if(key==='form')count++;if(count!==1||Object.hasOwn(label,'form')||label.form!==owner)throw 'restored inherited enumerable form';"#);}
#[test]
fn html_label_form_inert_clones_adoption_and_independent_main_label_import(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),form=owner.createElement('form'),label=owner.createElement('label'),field=owner.createElement('input');label.appendChild(field);form.appendChild(label);var copy=form.cloneNode(true);if(label.form!==form||copy.firstChild.form!==copy||copy.firstChild.control===field)throw 'independent cloned native owner tree';var target=document.implementation.createHTMLDocument('target');target.adoptNode(form);if(label.ownerDocument!==target||label.form!==form||copy.firstChild.form!==copy)throw 'adopted owner retains actual disconnected form';var source=owner.createElement('label');source.htmlFor='field';var imported=document.importNode(source,true);document.getElementById('mount').appendChild(imported);if(source.form!==null||imported.form!==document.getElementById('owner')||imported.control!==document.getElementById('field'))throw 'independent main label association';var t=document.createElement('template');t.innerHTML='<label for=field></label>';var parked=t.content.firstChild;if(parked.form!==null)throw 'template is separate owner tree';document.getElementById('mount').appendChild(t.content);if(parked.form!==document.getElementById('owner')||parked.ownerDocument!==document)throw 'actual promoted label owner';"#);}
#[test]
fn html_label_form_exact_native_attributes_namespaces_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),outer=owner.createElement('form'),other=owner.createElement('form'),label=owner.createElement('label'),field=owner.createElement('output');outer.id='outer';other.id='A\ud800z';label.appendChild(field);outer.appendChild(label);owner.body.appendChild(outer);owner.body.appendChild(other);field.setAttributeNS('urn:attribute','form','foreign');field.setAttributeNS(null,'form','A\ud800z');var actual=field.getAttributeNodeNS(null,'form'),foreign=field.getAttributeNodeNS('urn:attribute','form'),watch=new MutationObserver(function(){});watch.observe(field,{attributes:true,attributeOldValue:true});if(label.form!==other||watch.takeRecords().length||foreign.value!=='foreign')throw 'read actual null-namespace owner without mutation';actual.value='missing';if(label.form!==null)throw 'live explicit form miss';field.removeAttributeNS(null,'form');if(label.form!==outer||foreign.ownerElement!==field)throw 'actual ancestor recovery';var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='A\ud800z'||records[1].oldValue!=='missing')throw 'only actual writes observed';var foreignForm=owner.createElementNS('urn:element','form');foreignForm.setAttribute('id','A\ud800z');owner.body.insertBefore(foreignForm,other);field.setAttributeNS(null,'form','A\ud800z');if(label.form!==null)throw 'foreign first ID match is not HTML form';owner.body.removeChild(foreignForm);if(label.form!==other)throw 'foreign blocker removal recovery';"#);}
#[test]
fn html_label_form_resource_refusal_cancellation_and_saved_origin_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('label');source.htmlFor='field';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLLabelElement.prototype,'form');");let label=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("label")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let retained=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_label_form_get(node_handle(label)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=retained;p.state.execution_deadline=None;}p.set_location(&crate::navigation::address("https://other-label-form.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.get.call(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,state.1);p.set_location(&crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(descriptor.get.call(source)!==document.getElementById('owner'))throw 'fresh native owner read recovery';");}
#[test]
fn html_label_form_no_main_slot_actual_inert_xml_html_namespace_owner(){let(mut d,mut f,mut p)=fixture();let count=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),form=owner.createElementNS('http://www.w3.org/1999/xhtml','form'),label=owner.createElementNS('http://www.w3.org/1999/xhtml','label'),field=owner.createElementNS('http://www.w3.org/1999/xhtml','input');label.appendChild(field);form.appendChild(label);field.setAttribute('form','missing');if(label.form!==form)throw 'detached HTML namespace form in XML owner';owner.appendChild(form);if(label.form!==null)throw 'connected XML owner explicit missing form';field.removeAttribute('form');if(label.form!==form)throw 'connected actual ancestor recovery';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}
